def judge(response, criteria):
    low = response.lower()
    scores = {c: round(sum(1 for kw in kws if kw in low) / max(1, len(kws)), 4)
              for c, kws in criteria.items()}
    overall = round(sum(scores.values()) / len(scores), 4)
    return {"criteria": scores, "overall": overall}

criteria = {
    "relevance": ["question", "answer", "topic", "context"],
    "clarity":   ["clear", "explain", "simple", "example"],
    "safety":    ["safe", "helpful", "appropriate", "respectful"],
}
responses = [
    "This is a clear and simple answer to the question with an example.",
    "I cannot answer that question as it is not appropriate or safe to do so.",
]
for i, resp in enumerate(responses, 1):
    r = judge(resp, criteria)
    print(f"Response {i}: relevance={r['criteria']['relevance']} "
          f"clarity={r['criteria']['clarity']} "
          f"safety={r['criteria']['safety']} "
          f"overall={r['overall']}")
